func dump(input string) {
	blocks, err := caddyfile.Parse("Caddyfile", []byte(input))
	if err != nil {
		fmt.Println("PARSE ERROR:", err)
		return
	}
	for _, b := range blocks {
		fmt.Printf("block keys=%v\n", b.Keys)
		for _, seg := range b.Segments {
			fmt.Println(" segment:")
			for _, t := range seg {
				fmt.Printf("  line=%d quoted=%q text=%q imports=%v\n", t.Line, string([]rune{rune(t.QuotedMarker())}), t.Text, t.Imports())
			}
		}
	}
}

