package main

import (
	"fmt"
	"os"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
	"github.com/caddyserver/caddy/v2/caddyconfig/httpcaddyfile"
)

func main() {
	for i, input := range []string{
		// heredoc, spaces indent, top-level site no braces
		":8080\n\n@cel_tld_net <<CEL\n    {http.request.host.labels.0} == \"net\"\n    CEL\nrespond @cel_tld_net \"net\"\n",
		// heredoc inside braced site
		":8080 {\n    @cel_tld_net <<CEL\n        {http.request.host.labels.0} == \"net\"\n    CEL\n    respond @cel_tld_net \"net\"\n}\n",
		// backtick inside snippet
		"(s) {\n\t@g `{http.error.status_code} == 404`\n}\n:8080\nimport s\nabort @g\n",
		// heredoc inside snippet
		"(s) {\n\t@g <<CEL\n\t\t{http.error.status_code} == 404\n\tCEL\n}\n:8080\nimport s\nabort @g\n",
		// two-token backtick expression top level
		":8080\n\n@a `{http.request.host.labels.0}` == \"net\"\nrespond @a \"net\"\n",
	} {
		fmt.Printf("=== case %d ===\n", i)
		cfg, _, err := caddyfile.Adapter{ServerType: httpcaddyfile.ServerType{}}.Adapt([]byte(input), map[string]any{"filename": "Caddyfile"})
		if err != nil {
			fmt.Println("ERROR:", err)
		} else {
			fmt.Println(string(cfg))
		}
	}
	os.Exit(0)
}

